/* SPDX-License-Identifier: Apache-2.0
 * Expected bytes are derived independently from GB 46750-2025 Tables 1-3.
 * They are source fixtures, never regenerated by the encoder under test. */
#include "opendroneidcn.h"
#include <float.h>
#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define CHECK(x) do { if (!(x)) { \
    fprintf(stderr, "%s:%d: %s\n", __FILE__, __LINE__, #x); exit(1); \
} } while (0)

static DroneRIDData_t example(void)
{
    DroneRIDData_t d = {0};
    memcpy(d.sn, "12345678901234567890", 20);
    memcpy(d.uin, "ABCDEFGH", 8);
    d.drone_class = DRONE_CLASS_SMALL;
    d.gcs_pos_type = POS_TYPE_GCS;
    d.gcs_lon = 1; d.gcs_lat = -2; d.gcs_alt = 100;
    d.drone_lon = -3; d.drone_lat = 4; d.drone_alt = 200;
    d.track_angle = 123.49f; d.ground_speed = 12.39f;
    d.op_status = OP_STATUS_AIR;
    d.horizontal_accuracy = 9; d.vertical_accuracy = 4; d.speed_accuracy = 3;
    d.timestamp_ms = UINT64_C(0x060504030201); d.timestamp_accuracy = 5;
    return d;
}

static size_t load_vector(const char *name, uint8_t *buf, size_t size)
{
    char path[1024];
    CHECK(snprintf(path, sizeof(path), "%s/%s.hex", CN_VECTOR_DIR, name) > 0);
    FILE *f = fopen(path, "r"); CHECK(f != NULL);
    size_t len = 0; unsigned byte;
    while (fscanf(f, "%2x", &byte) == 1) {
        CHECK(len < size); CHECK(byte <= 255); buf[len++] = (uint8_t)byte;
    }
    CHECK(feof(f)); CHECK(fclose(f) == 0);
    return len;
}

static void expect_vector(const DroneRIDData_t *d, const char *name, size_t wanted)
{
    uint8_t expected[128], actual[128]; size_t length = 99;
    size_t n = load_vector(name, expected, sizeof(expected)); CHECK(n == wanted);
    memset(actual, 0xa5, sizeof(actual));
    CHECK(CN46750_RID_Encode(d, actual, sizeof(actual), &length) == RID_OK);
    CHECK(length == n);
    for (size_t i = 0; i < n; ++i) {
        if (actual[i] != expected[i]) {
            fprintf(stderr, "%s byte %zu: expected %02x, got %02x\n", name, i, expected[i], actual[i]);
            exit(1);
        }
    }
    CHECK(actual[n] == 0xa5);
}

static void golden_frames(void)
{
    DroneRIDData_t d = example();
    expect_vector(&d, "mandatory", CN46750_MIN_PACKET_SIZE);
    d.has_op_category = true; d.op_category = OP_CATEGORY_SPECIFIC;
    d.has_rel_alt = true; d.rel_alt = 10;
    d.has_v_speed = true; d.vertical_speed = -2.5f;
    d.has_pressure_alt = true; d.pressure_alt = 50;
    expect_vector(&d, "all_fields", CN46750_MAX_PACKET_SIZE);

    uint8_t frame[128]; DroneRIDData_t decoded; uint8_t version = 99;
    size_t len = load_vector("all_fields", frame, sizeof(frame));
    CHECK(CN46750_RID_Decode(frame, len, &decoded, &version) == RID_OK);
    CHECK(version == 0 && decoded.unknown_fields == 0);
    CHECK(decoded.gcs_lon == 1 && decoded.gcs_lat == -2);
    CHECK(decoded.drone_lon == -3 && decoded.drone_lat == 4);
    CHECK(decoded.rel_alt == 10 && decoded.vertical_speed == -2.5f);
    CHECK(decoded.pressure_alt == 50 && decoded.drone_alt == 200);
    CHECK(decoded.track_angle == 123.4f && decoded.ground_speed == 12.3f);
    CHECK(decoded.timestamp_ms == UINT64_C(0x060504030201));
}

static void unknown_and_zero(void)
{
    DroneRIDData_t d = example();
    memset(d.uin, 0, sizeof(d.uin));
    d.unknown_fields = CN46750_UNKNOWN_ALL;
    d.op_status = OP_STATUS_FAIL_NORMAL;
    d.horizontal_accuracy = d.vertical_accuracy = d.speed_accuracy = d.timestamp_accuracy = 0;
    d.gcs_lon = NAN; d.drone_alt = INFINITY;
    expect_vector(&d, "unknown", CN46750_MIN_PACKET_SIZE);

    uint8_t frame[128]; DroneRIDData_t decoded; size_t len;
    len = load_vector("unknown", frame, sizeof(frame));
    CHECK(CN46750_RID_Decode(frame, len, &decoded, NULL) == RID_OK);
    uint32_t mandatory_unknown = CN46750_UNKNOWN_ALL &
        ~(CN46750_UNKNOWN_REL_ALTITUDE | CN46750_UNKNOWN_VERTICAL_SPEED | CN46750_UNKNOWN_PRESSURE_ALTITUDE);
    CHECK(decoded.unknown_fields == mandatory_unknown);
    CHECK(decoded.uin[0] == 0);
    expect_vector(&decoded, "unknown", CN46750_MIN_PACKET_SIZE);

    d = example(); d.gcs_lon = d.gcs_lat = d.drone_lon = d.drone_lat = 0;
    d.has_v_speed = true; d.vertical_speed = 0;
    CHECK(CN46750_RID_Encode(&d, frame, sizeof(frame), &len) == RID_OK);
    CHECK(CN46750_RID_Decode(frame, len, &decoded, NULL) == RID_OK);
    CHECK(decoded.unknown_fields == 0 && decoded.vertical_speed == 0);
    d.unknown_fields = CN46750_UNKNOWN_VERTICAL_SPEED; d.vertical_speed = NAN;
    CHECK(CN46750_RID_Encode(&d, frame, sizeof(frame), &len) == RID_OK);
    CHECK(frame[58] == 0xff);
    CHECK(CN46750_RID_Decode(frame, len, &decoded, NULL) == RID_OK);
    CHECK(decoded.unknown_fields == CN46750_UNKNOWN_VERTICAL_SPEED);
}

static void reject_input(DroneRIDData_t d)
{
    uint8_t frame[128]; size_t len = 99;
    memset(frame, 0xa5, sizeof(frame));
    CHECK(CN46750_RID_Encode(&d, frame, sizeof(frame), &len) == RID_ERR_PARAM);
    CHECK(len == 0 && frame[0] == 0xa5);
}

#define REJECT(member, value) do { DroneRIDData_t bad = example(); bad.member = (value); reject_input(bad); } while (0)
static void validation(void)
{
    REJECT(gcs_lon, 180.1); REJECT(gcs_lat, -90.1); REJECT(drone_lat, 90.1);
    REJECT(drone_lon, DBL_MAX); REJECT(gcs_lon, NAN); REJECT(drone_lat, INFINITY);
    REJECT(drone_lon, -0.0000001); /* Reserved sentinel collision. */
    REJECT(track_angle, -1); REJECT(track_angle, 360); REJECT(track_angle, NAN);
    REJECT(ground_speed, -1); REJECT(ground_speed, 6553.5f);
    REJECT(gcs_alt, -1000); REJECT(drone_alt, 31768); REJECT(drone_alt, INFINITY);
    REJECT(drone_class, (DroneClass_t)5); REJECT(drone_class, (DroneClass_t)-1);
    REJECT(gcs_pos_type, (PositionType_t)2); REJECT(op_status, (OperationStatus_t)6);
    REJECT(coord_system, (CoordSystem_t)2); REJECT(horizontal_accuracy, 13);
    REJECT(vertical_accuracy, 7); REJECT(speed_accuracy, 5); REJECT(timestamp_accuracy, 9);
    REJECT(timestamp_ms, UINT64_C(0x1000000000000)); REJECT(unknown_fields, UINT32_C(1));
    REJECT(sn[0], 0); REJECT(sn[3], (char)0x80); REJECT(sn[20], 'X'); REJECT(uin[8], 'X');
    DroneRIDData_t d = example(); d.has_v_speed = true; d.vertical_speed = -63.5f; reject_input(d);
    d = example(); d.has_rel_alt = true; d.rel_alt = -9000; reject_input(d);
    d = example(); d.has_pressure_alt = true; d.pressure_alt = NAN; reject_input(d);
    d = example(); d.has_op_category = true; d.op_category = (OperationCategory_t)4; reject_input(d);
}

static void boundaries(void)
{
    uint8_t frame[128]; size_t len; DroneRIDData_t decoded;
    DroneRIDData_t d = example(); d.track_angle = 359.99f; d.ground_speed = 6553.4f;
    d.timestamp_ms = CN46750_MAX_TIMESTAMP;
    d.gcs_lon = 180; d.gcs_lat = -90; d.drone_lon = -180; d.drone_lat = 90;
    d.gcs_alt = -999.5f; d.drone_alt = 31767.5f;
    CHECK(CN46750_RID_Encode(&d, frame, sizeof(frame), &len) == RID_OK);
    CHECK(frame[54] == 0x0f && frame[55] == 0x0e); /* 3599 */
    CHECK(frame[56] == 0xfe && frame[57] == 0xff); /* 65534 */
    CHECK(frame[44] == 1 && frame[45] == 0);
    CHECK(frame[58] == 0xff && frame[59] == 0xff);
    for (size_t i = 65; i < 71; ++i) CHECK(frame[i] == 0xff);
    CHECK(CN46750_RID_Decode(frame, len, &decoded, NULL) == RID_OK);
    d.has_v_speed = true; d.vertical_speed = -63;
    CHECK(CN46750_RID_Encode(&d, frame, sizeof(frame), &len) == RID_OK && frame[58] == 0xfe);
    d.vertical_speed = 63.5f;
    CHECK(CN46750_RID_Encode(&d, frame, sizeof(frame), &len) == RID_OK && frame[58] == 0x7f);
    d = example(); d.track_angle = 0.09f; d.ground_speed = 0.09f;
    CHECK(CN46750_RID_Encode(&d, frame, sizeof(frame), &len) == RID_OK);
    CHECK(frame[54] == 0 && frame[56] == 0);
    /* Decimal tenths arriving as float must retain their intended code.
     * In particular, promote-to-double then floor would turn 0.7f into 6. */
    for (unsigned code = 0; code < 3600; ++code) {
        d.track_angle = (float)code / 10.0f;
        CHECK(CN46750_RID_Encode(&d, frame, sizeof(frame), &len) == RID_OK);
        CHECK(((unsigned)frame[54] | ((unsigned)frame[55] << 8)) == code);
    }
    for (unsigned code = 0; code <= 65534; ++code) {
        d.ground_speed = (float)code / 10.0f;
        CHECK(CN46750_RID_Encode(&d, frame, sizeof(frame), &len) == RID_OK);
        CHECK(((unsigned)frame[56] | ((unsigned)frame[57] << 8)) == code);
    }
}

static void malformed_frames(void)
{
    uint8_t original[128], frame[128]; DroneRIDData_t decoded;
    size_t n = load_vector("mandatory", original, sizeof(original));
    for (size_t len = 0; len < n; ++len)
        CHECK(CN46750_RID_Decode(original, len, &decoded, NULL) < 0);
    const size_t reserved_offsets[] = {34, 35, 60, 61, 62, 63, 64, 71};
    const uint8_t reserved_values[] = {5, 2, 6, 2, 13, 7, 5, 9};
    for (size_t i = 0; i < sizeof(reserved_offsets)/sizeof(reserved_offsets[0]); ++i) {
        memcpy(frame, original, n); frame[reserved_offsets[i]] = reserved_values[i];
        CHECK(CN46750_RID_Decode(frame, n, &decoded, NULL) < 0);
    }
    memcpy(frame, original, n); frame[34] = 0x12;
    CHECK(CN46750_RID_Decode(frame, n, &decoded, NULL) < 0);
    memcpy(frame, original, n); frame[3] &= (uint8_t)~0x40;
    CHECK(CN46750_RID_Decode(frame, n, &decoded, NULL) < 0);
    memcpy(frame, original, n); frame[2]++; frame[n] = 0;
    CHECK(CN46750_RID_Decode(frame, n + 1, &decoded, NULL) < 0);
    memset(frame, 0xff, sizeof(frame)); frame[1] = 0x20; frame[2] = 66;
    CHECK(CN46750_RID_Decode(frame, sizeof(frame), &decoded, NULL) < 0);
    CHECK(!CN46750_FindPacket(frame, sizeof(frame), NULL, NULL));
    /* An explicit extra flag byte reports partial extension support. */
    memcpy(frame, original, 6); frame[5] |= 1; frame[6] = 0;
    memcpy(frame + 7, original + 6, n - 6);
    CHECK(CN46750_RID_Decode(frame, n + 1, &decoded, NULL) == RID_OK_EXTENSION);
    memcpy(frame + 3, original, n); frame[0] = frame[1] = frame[2] = 0;
    size_t offset = 0, length = 0;
    CHECK(CN46750_FindPacket(frame, n + 3, &offset, &length));
    CHECK(offset == 3 && length == n);
    /* Wrong-length buffers must not be touched. */
    DroneRIDData_t d = example(); memset(frame, 0xa5, sizeof(frame));
    CHECK(CN46750_RID_Encode(&d, frame, n - 1, &length) == RID_ERR_INVALID_LEN);
    CHECK(length == 0 && frame[0] == 0xa5);
}

int main(void)
{
    golden_frames(); unknown_and_zero(); validation(); boundaries(); malformed_frames();
    puts("CN46750: golden frames, unknown values, boundaries and malformed inputs passed");
    return 0;
}
